// ============================================================
// BUILD DESIRED STATE
// ------------------------------------------------------------
// Collapses the incoming items into ONE item per email carrying the tag
// set that SHOULD be on the member (the "master sheet" side of the diff).
//
// Accepts either shape, mixed is fine:
//   { email, tags: ["VIC","Metro","Active", ...] }   <- preferred
//   { email, tagName: "Active" }                     <- legacy, one item per tag
//
// No decisions about removal are made here — that needs the member's
// current tags, which are fetched in the next node.
// ============================================================

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const clean = (t) => String(t == null ? '' : t).replace(/\s+/g, ' ').trim();

const byEmail = new Map();

for (const item of $input.all()) {
  const d = item.json || {};
  const email = String(d.email == null ? '' : d.email).toLowerCase().trim();
  if (!email || !EMAIL_RE.test(email)) continue;

  const raw = Array.isArray(d.tags) ? d.tags : (d.tagName ? [d.tagName] : []);
  if (!byEmail.has(email)) byEmail.set(email, new Set());
  const set = byEmail.get(email);
  for (const t of raw) {
    const c = clean(t);
    if (c) set.add(c);
  }
}

const out = [];
for (const [email, tags] of byEmail) {
  if (tags.size === 0) continue; // nothing to say about this member
  out.push({ json: { email, desiredTags: [...tags] } });
}

return out;

// ============================================================
// DIFF TAGS — decide what to remove and what to add
// ------------------------------------------------------------
//   current tags   <- fetched from Mailchimp by the previous node
//   desired tags   <- from the segmentation payload (master sheet)
//
//   tags to remove = current  MINUS  desired   (managed values only)
//   tags to add    = desired  MINUS  current
//
// SCOPE RULE: a tag is only ever removed if it belongs to a group this
// run actually has an opinion about. An abandoned-cart run that only
// supplies ["Abandoned Cart","Shopify"] has no opinion on activity or
// tier, so it removes nothing. Anything outside the managed vocabulary
// (VIP, campaign tags, Shopify, Fieldfolio...) is never removed.
// ============================================================

// ---- GUARD: every Mailchimp node must talk to the same audience ----
// A removal sent to the wrong audience returns 204 and changes nothing, so a
// mismatch is completely invisible at runtime: the node reports success and the
// tag stays put. Fail loudly instead of silently doing nothing.
const MAILCHIMP_NODES = ['Fetch Current Tags', 'Remove One Tag', 'Add One Tag'];
let configuredLists = null;
try {
  configuredLists = MAILCHIMP_NODES.map((n) => ({ node: n, list: $(n).params.list }));
} catch (e) {
  configuredLists = null; // .params unavailable on this n8n version
}
if (configuredLists) {
  const distinct = [...new Set(configuredLists.map((l) => l.list))];
  if (distinct.length > 1) {
    throw new Error(
      'Mailchimp nodes point at different audiences -> '
      + configuredLists.map((l) => l.node + '=' + l.list).join(', ')
      + '. Tag removals would go to the wrong audience and silently do nothing. '
      + 'Set the same List (and the same credential) on every Mailchimp node.',
    );
  }
}

// Mutually exclusive groups. Order = precedence if a payload somehow
// arrives with two values from the same group.
const GROUPS = {
  activity: ['Active', 'Inactive'],
  spendTier: ['Tier A', 'Tier B', 'Tier C'],
  geo: ['Metro', 'Regional'],
  state: ['NSW', 'VIC', 'QLD', 'SA', 'WA', 'TAS', 'ACT', 'NT'],
  businessType: ['Gift & Homewares', 'Furniture', 'Manchester', 'Interior Stylist', 'Other'],
};

// Old / renamed values that may still be sitting on members. Removed, never
// added. Populate from Mailchimp > Audience > Tags after an audit.
const RETIRED = {
  activity: [],
  spendTier: [],
  geo: [],
  state: [],
  businessType: [],
};

// ---- desired state (this run) ----
const source = $('Loop Over Members').first(1).json;
const email = source.email;

// ---- current state (from Mailchimp) ----
const member = $input.first().json || {};
const memberFound = Array.isArray(member.tags);
const currentTags = memberFound ? member.tags.map((t) => t && t.name).filter(Boolean) : [];
const fetchError = member.error ? String(member.error.message || member.error) : null;

// ---- canonical lookup so 'tier a' and 'Tier  A' resolve to 'Tier A' ----
const canonical = new Map();
for (const [group, values] of Object.entries(GROUPS)) {
  for (const v of values) canonical.set(v.toLowerCase(), v);
  for (const v of RETIRED[group] || []) canonical.set(v.toLowerCase(), v);
}
const clean = (t) => String(t == null ? '' : t).replace(/\s+/g, ' ').trim();
const normalize = (t) => {
  const c = clean(t);
  return canonical.get(c.toLowerCase()) || c;
};

const desiredSet = new Set((source.desiredTags || []).map(normalize).filter(Boolean));

// ---- work out which groups this run has an opinion about ----
const conflicts = [];
const groupsInScope = [];
const managedInScope = new Map(); // lowercased -> canonical

for (const [group, values] of Object.entries(GROUPS)) {
  const present = values.filter((v) => desiredSet.has(v));
  if (present.length === 0) continue;

  groupsInScope.push(group);
  if (present.length > 1) {
    conflicts.push({ group, received: present, kept: present[0] });
    for (const loser of present.slice(1)) desiredSet.delete(loser);
  }
  for (const v of values.concat(RETIRED[group] || [])) managedInScope.set(v.toLowerCase(), v);
}

const desiredTags = [...desiredSet];
const desiredLc = new Set(desiredTags.map((t) => t.toLowerCase()));
const currentLc = new Set(currentTags.map((t) => t.toLowerCase()));

// Remove using the tag name EXACTLY as Mailchimp stores it.
const tagsToRemove = currentTags.filter(
  (t) => managedInScope.has(t.toLowerCase()) && !desiredLc.has(t.toLowerCase()),
);

// Skip tags already on the member: re-adding is a no-op but pointless, and
// skipping keeps tag-based automations from being poked every week.
const tagsToAdd = desiredTags.filter((t) => !currentLc.has(t.toLowerCase()));

// Left alone on purpose — outside the managed vocabulary for this run.
const untouched = currentTags.filter((t) => !managedInScope.has(t.toLowerCase()));

// Right tag, wrong casing. Reported rather than auto-fixed: removing and
// re-adding would re-trigger any automation keyed on that tag.
const casingDrift = currentTags.filter(
  (t) => desiredLc.has(t.toLowerCase()) && !desiredTags.includes(t),
);

const removeLc = new Set(tagsToRemove.map((t) => t.toLowerCase()));
const expectedAfter = currentTags
  .filter((t) => !removeLc.has(t.toLowerCase()))
  .concat(tagsToAdd);

return [{
  json: {
    email,
    memberFound,
    memberListId: member.list_id || null,
    fetchError,
    currentTags,
    desiredTags,
    groupsInScope,
    tagsToRemove,
    tagsToAdd,
    untouched,
    casingDrift,
    conflicts,
    expectedAfter,
    hasRemovals: tagsToRemove.length > 0,
    hasAdds: tagsToAdd.length > 0,
  },
}];

// One item per tag, so the Mailchimp node makes ONE call per tag instead of
// sending an array. Runs once for all items, so it emits exactly the removal
// list regardless of how many items arrive.
const d = $('Diff Tags').first(0).json;

return (d.tagsToRemove || []).map((tagName) => ({
  json: { email: d.email, tagName, op: 'remove' },
}));

// One item per tag, so the Mailchimp node makes ONE call per tag instead of
// sending an array. Reads from Diff Tags rather than its own input, so a
// preceding removal call cannot change what gets added.
const d = $('Diff Tags').first(0).json;

return (d.tagsToAdd || []).map((tagName) => ({
  json: { email: d.email, tagName, op: 'add' },
}));

// Compares what Mailchimp ACTUALLY holds after the writes against what we
// asked for. The Mailchimp node hardcodes `{ success: true }` after every
// call, so its output only means "no HTTP error" — it is not evidence that
// anything changed. This node is that evidence.
const d = $('Diff Tags').first(0).json;
const verify = $input.first().json || {};

const actualTags = Array.isArray(verify.tags)
  ? verify.tags.map((t) => t && t.name).filter(Boolean)
  : null;

let verified = null;
let stillPresent = [];
let missing = [];

if (actualTags) {
  const actualLc = new Set(actualTags.map((t) => t.toLowerCase()));
  // asked to be removed, but Mailchimp still has it
  stillPresent = d.tagsToRemove.filter((t) => actualLc.has(t.toLowerCase()));
  // asked to be added, but Mailchimp does not have it
  missing = d.tagsToAdd.filter((t) => !actualLc.has(t.toLowerCase()));
  verified = stillPresent.length === 0 && missing.length === 0;
}

return [{
  json: {
    email: d.email,
    memberFound: d.memberFound,
    before: d.currentTags,
    removed: d.tagsToRemove,
    added: d.tagsToAdd,
    after: actualTags,
    verified,
    stillPresent,
    missing,
    untouched: d.untouched,
    casingDrift: d.casingDrift,
    conflicts: d.conflicts,
    error: d.fetchError
      || (verify.error ? String(verify.error.message || verify.error) : null)
      || (stillPresent.length ? `Mailchimp accepted the call but did not remove: ${stillPresent.join(', ')}` : null)
      || (missing.length ? `Mailchimp accepted the call but did not add: ${missing.join(', ')}` : null),
    syncedAt: new Date().toISOString(),
  },
}];
